mapper.insert:
BEGIN
INSERT INTO TB_PRODUCT_TERMS ( TERMS_TITLE, TERMS_TYPE, PDF_URL, IMAGE_URL, TERMS_SUMMARY, TERMS_VERSION, USE_YN ) VALUES ( #{terms_title}, #{terms_type}, #{pdf_url}, #{image_url, jdbcType=VARCHAR}, #{terms_summary}, #{terms_version}, #{use_yn}) RETURNING terms_no INTO #{terms_no, mode=OUT, jdbcType=NUMERIC};
END;
